const Foam::edgeList& Foam::cyclicPolyPatch::coupledPoints() const
{
    if (!coupledPointsPtr_)
    {
        const faceList& nbrLocalFaces = nbrPatch().localFaces();
        const labelList& nbrMeshPoints = nbrPatch().meshPoints();

        // Now all we know is that relative face index in *this is same
        // as coupled face in nbrPatch and also that the 0th vertex
        // corresponds.

        // From local point to nbrPatch or -1.
        labelList coupledPoint(nPoints(), -1);

        forAll(*this, patchFacei)
        {
            const face& fA = localFaces()[patchFacei];
            const face& fB = nbrLocalFaces[patchFacei];

            forAll(fA, indexA)
            {
                label patchPointA = fA[indexA];

                if (coupledPoint[patchPointA] == -1)
                {
                    label indexB = (fB.size() - indexA) % fB.size();

                    // Filter out points on wedge axis
                    if (meshPoints()[patchPointA] != nbrMeshPoints[fB[indexB]])
                    {
                        coupledPoint[patchPointA] = fB[indexB];
                    }
                }
            }
        }

        coupledPointsPtr_ = new edgeList(nPoints());
        edgeList& connected = *coupledPointsPtr_;

        // Extract coupled points.
        label connectedI = 0;

        forAll(coupledPoint, i)
        {
            if (coupledPoint[i] != -1)
            {
                connected[connectedI++] = edge(i, coupledPoint[i]);
            }
        }

        connected.setSize(connectedI);

        if (debug)
        {
            OFstream str
            (
                boundaryMesh().mesh().time().path()
               /name() + "_coupledPoints.obj"
            );
            label vertI = 0;

            Pout<< "Writing file " << str.name() << " with coordinates of "
                << "coupled points" << endl;

            forAll(connected, i)
            {
                const point& a = points()[meshPoints()[connected[i][0]]];
                const point& b = points()[nbrMeshPoints[connected[i][1]]];

                str<< "v " << a.x() << ' ' << a.y() << ' ' << a.z() << nl;
                str<< "v " << b.x() << ' ' << b.y() << ' ' << b.z() << nl;
                vertI += 2;

                str<< "l " << vertI-1 << ' ' << vertI << nl;
            }
        }
    }

static AVStream *add_audio_stream(AVFormatContext *oc, AVCodecID codec_id)
{
    AVCodecContext *c;
    AVStream *st;

    st = avformat_new_stream(oc, NULL);
    if (!st) {
        yCFatal(FFMPEGWRITER, "Could not alloc stream");
    }

    c = st->codec;
    c->codec_id = codec_id;
    c->codec_type = AVMEDIA_TYPE_AUDIO;

    /* put sample parameters */
    c->bit_rate = 64000;
    c->sample_rate = 44100;
    c->channels = 2;
    return st;
}

static void open_audio(AVFormatContext *oc, AVStream *st)
{
    yCInfo(FFMPEGWRITER, "Opening audio stream");
    AVCodecContext *c;
    AVCodec *codec;

    c = st->codec;

    /* find the audio encoder */
    codec = avcodec_find_encoder(c->codec_id);
    if (!codec) {
        yCFatal(FFMPEGWRITER, "Audio codec not found");
    }

    /* open it */
    if (avcodec_open2(c, codec, nullptr) < 0) {
        yCFatal(FFMPEGWRITER, "Could not open codec");
    }

    /* init signal generator */
    t = 0;
    tincr = 2 * M_PI * 110.0 / c->sample_rate;
    /* increment frequency by 110 Hz per second */
    tincr2 = 2 * M_PI * 110.0 / c->sample_rate / c->sample_rate;

    audio_outbuf_size = 10000;
    audio_outbuf = (uint8_t*)av_malloc(audio_outbuf_size);

    /* ugly hack for PCM codecs (will be removed ASAP with new PCM
       support to compute the input frame size in samples */
    if (c->frame_size <= 1) {
        audio_input_frame_size = audio_outbuf_size / c->channels;
        switch(st->codec->codec_id) {
        case AV_CODEC_ID_PCM_S16LE:
        case AV_CODEC_ID_PCM_S16BE:
        case AV_CODEC_ID_PCM_U16LE:
        case AV_CODEC_ID_PCM_U16BE:
            audio_input_frame_size >>= 1;
            break;
        default:
            break;
        }
    } else {
        audio_input_frame_size = c->frame_size;
    }
    samples_size = audio_input_frame_size;
    samples_at = 0;
    samples_channels = c->channels;
    samples = (int16_t*)av_malloc(samples_size*2*samples_channels);


    yCFatal(FFMPEGWRITER,
            "FRAME SIZE is %d / samples size is %d\n",
            c->frame_size,
            samples_size);
}

static void get_audio_frame(int16_t *samples, int frame_size, int nb_channels)
{
    int j, i, v;
    int16_t *q;

    q = samples;
    for(j=0;j<frame_size;j++) {
        v = (int)(sin(t) * 10000);
        for(i = 0; i < nb_channels; i++)
            *q++ = v;
        t += tincr;
        tincr += tincr2;
    }
}

static void make_audio_frame(AVCodecContext *c, AVFrame * &frame,
                             void *&samples) {
    frame = av_frame_alloc();
    if (!frame) {
        yCFatal(FFMPEGWRITER, "Could not allocate audio frame");
    }
    frame->nb_samples     = c->frame_size;
    frame->format         = c->sample_fmt;
    frame->channel_layout = c->channel_layout;
    int buffer_size = av_samples_get_buffer_size(nullptr, c->channels,
                                                 c->frame_size,
                                                 c->sample_fmt, 0);
    if (buffer_size < 0) {
        yCError(FFMPEGWRITER, "Could not get sample buffer size");
    }
    samples = av_malloc(buffer_size);
    if (!samples) {
        yCFatal(FFMPEGWRITER,
                "Could not allocate %d bytes for samples buffer",
                buffer_size);
    }
    /* setup the data pointers in the AVFrame */
    int ret = avcodec_fill_audio_frame(frame, c->channels, c->sample_fmt,
                                       (const uint8_t*)samples, buffer_size, 0);
    if (ret < 0) {
        yCFatal(FFMPEGWRITER, "Could not setup audio frame");
    }
}

static void write_audio_frame(AVFormatContext *oc, AVStream *st)
{
    AVCodecContext *c;
    AVPacket pkt;
    av_init_packet(&pkt);

    c = st->codec;

    get_audio_frame(samples, audio_input_frame_size, c->channels);

    AVFrame *frame;
    void *samples;
    make_audio_frame(c,frame,samples);
    AVPacket tmp;
    int got_packet = 0;
    av_init_packet(&tmp);
    tmp.data = audio_outbuf;
    tmp.size = audio_outbuf_size;
    pkt.size = avcodec_encode_audio2(c, &tmp, frame, &got_packet);
    if (tmp.side_data_elems > 0) {
        for (int i = 0; i < tmp.side_data_elems; i++) {
            av_free(tmp.side_data[i].data);
        }
        av_freep(&tmp.side_data);
        tmp.side_data_elems = 0;
    }
    av_freep(&samples);
    av_frame_free(&frame);

    pkt.pts= av_rescale_q(c->coded_frame->pts, c->time_base, st->time_base);
    pkt.flags |= AV_PKT_FLAG_KEY;
    pkt.stream_index= st->index;
    pkt.data= audio_outbuf;

    /* write the compressed frame in the media file */
    if (av_write_frame(oc, &pkt) != 0) {
        yCFatal(FFMPEGWRITER, "Error while writing audio frame");
    } else {
        yCInfo(FFMPEGWRITER, "Wrote some audio");
    }
}

static void write_audio_frame(AVFormatContext *oc, AVStream *st, Sound& snd)
{
    yCInfo(FFMPEGWRITER, "Preparing to write audio (%d left over)", samples_at);
    AVCodecContext *c;
    int key = 1;

    c = st->codec;

    size_t at = 0;
    while (at<snd.getSamples()) {

        int avail = samples_size - samples_at;
        int remain = snd.getSamples() - at;
        int chan = snd.getChannels();
        if (remain<avail) { avail = remain; }
        for (int i=0; i<avail; i++) {
            int offset = samples_at*samples_channels;
            for (int j=0; j<samples_channels; j++) {
                samples[offset+j] = snd.get(at,j%chan);
            }
            samples_at++;
            at++;
        }
        avail = samples_size - samples_at;

        if (avail==0) {
            AVPacket pkt;
            av_init_packet(&pkt);


            AVFrame *frame;
            void *samples;
            make_audio_frame(c,frame,samples);
            AVPacket tmp;
            int got_packet = 0;
            av_init_packet(&tmp);
            tmp.data = audio_outbuf;
            tmp.size = audio_outbuf_size;
            pkt.size = avcodec_encode_audio2(c, &tmp, frame, &got_packet);
            if (tmp.side_data_elems > 0) {
                for (int i = 0; i < tmp.side_data_elems; i++) {
                    av_free(tmp.side_data[i].data);
                }
                av_freep(&tmp.side_data);
                tmp.side_data_elems = 0;
            }
            av_freep(&samples);
            av_frame_free(&frame);

            pkt.pts= av_rescale_q(c->coded_frame->pts, c->time_base,
                                  st->time_base);
            pkt.dts = pkt.pts;
            yCTrace(FFMPEGWRITER, "(%d)", pkt.size);
            if (key) {
                pkt.flags |= AV_PKT_FLAG_KEY;
                key = 0;
            }
            pkt.stream_index= st->index;
            pkt.data = audio_outbuf;
            pkt.duration = 0;


            /* write the compressed frame in the media file */
            if (av_write_frame(oc, &pkt) != 0) {
                yCFatal(FFMPEGWRITER, "Error while writing audio frame");
            }
            samples_at = 0;
        }
    }
    yCInfo(FFMPEGWRITER, " wrote audio\n");
}

static void close_audio(AVFormatContext *oc, AVStream *st)
{
    avcodec_close(st->codec);

    av_free(samples);
    av_free(audio_outbuf);
}

static AVStream *add_video_stream(AVFormatContext *oc, AVCodecID codec_id,
                                  int w, int h, int framerate)
{
    AVCodecContext *c;
    AVStream *st;

    st = avformat_new_stream(oc, NULL);
    if (!st) {
        yCFatal(FFMPEGWRITER, "Could not alloc stream");
    }

    c = st->codec;
    c->codec_id = codec_id;
    c->codec_type = AVMEDIA_TYPE_VIDEO;

    /* put sample parameters */
    c->bit_rate = 400000;
    /* resolution must be a multiple of two */
    c->width = w;
    c->height = h;
    /* time base: this is the fundamental unit of time (in seconds) in terms
       of which frame timestamps are represented. for fixed-fps content,
       timebase should be 1/framerate and timestamp increments should be
       identically 1. */
    c->time_base.den = framerate;
    c->time_base.num = 1;
    c->gop_size = 12; /* emit one intra frame every twelve frames at most */
    c->pix_fmt = STREAM_PIX_FMT;
    if (c->codec_id == AV_CODEC_ID_MPEG2VIDEO) {
        /* just for testing, we also add B frames */
        c->max_b_frames = 2;
    }
    if (c->codec_id == AV_CODEC_ID_MPEG1VIDEO){
        /* needed to avoid using macroblocks in which some coeffs overflow
           this doesnt happen with normal video, it just happens here as the
           motion of the chroma plane doesnt match the luma plane */
        c->mb_decision=2;
    }
    // some formats want stream headers to be separate
    if(!strcmp(oc->oformat->name, "mp4") || !strcmp(oc->oformat->name, "mov") || !strcmp(oc->oformat->name, "3gp"))
        c->flags |= AV_CODEC_FLAG_GLOBAL_HEADER;


    return st;
}

static AVFrame *alloc_picture(int pix_fmt, int width, int height)
{
    AVFrame *picture;
    uint8_t *picture_buf;
    int size;

    picture = av_frame_alloc();
    if (!picture)
        return nullptr;
    size = avpicture_get_size((AVPixelFormat)pix_fmt, width, height);
    picture_buf = (uint8_t*)av_malloc(size);
    if (!picture_buf) {
        av_free(picture);
        return nullptr;
    }
    avpicture_fill((AVPicture *)picture, picture_buf,
                   (AVPixelFormat)pix_fmt, width, height);
    return picture;
}

void FfmpegWriter::open_video(AVFormatContext *oc, AVStream *st)
{
    yCInfo(FFMPEGWRITER, "Opening video stream");
    AVCodec *codec;
    AVCodecContext *c;

    c = st->codec;

    /* find the video encoder */
    codec = avcodec_find_encoder(c->codec_id);
    if (!codec) {
        yCFatal(FFMPEGWRITER, "Video codec not found");
    }

    /* open the codec */
    if (avcodec_open2(c, codec, nullptr) < 0) {
        yCFatal(FFMPEGWRITER, "Could not open codec");
    }

    video_outbuf = nullptr;
    /* allocate output buffer */
    /* XXX: API change will be done */
    /* buffers passed into lav* can be allocated any way you prefer,
       as long as they're aligned enough for the architecture, and
       they're freed appropriately (such as using av_free for buffers
       allocated with av_malloc) */
    video_outbuf_size = 200000;
    video_outbuf = (uint8_t*)av_malloc(video_outbuf_size);

    /* allocate the encoded raw picture */
    picture = alloc_picture(c->pix_fmt, c->width, c->height);
    if (!picture) {
        yCFatal(FFMPEGWRITER, "Could not allocate picture");
    }

    /* if the output format is not YUV420P, then a temporary YUV420P
       picture is needed too. It is then converted to the required
       output format */
    tmp_picture = nullptr;
    if (c->pix_fmt != AV_PIX_FMT_RGB24) {
        tmp_picture = alloc_picture(AV_PIX_FMT_RGB24, c->width, c->height);
        if (!tmp_picture) {
            yCFatal(FFMPEGWRITER, "Could not allocate temporary picture");
        }
    }
}

static BufFile *
makeBufFileCommon(int nfiles)
{
	BufFile    *file = (BufFile *) palloc(sizeof(BufFile));

	file->numFiles = nfiles;
	file->isInterXact = false;
	file->dirty = false;
	file->resowner = CurrentResourceOwner;
	file->curFile = 0;
	file->curOffset = 0L;
	file->pos = 0;
	file->nbytes = 0;

	return file;
}

static BufFile *
makeBufFile(File firstfile)
{
	BufFile    *file = makeBufFileCommon(1);

	file->files = (File *) palloc(sizeof(File));
	file->files[0] = firstfile;
	file->readOnly = false;
	file->fileset = NULL;
	file->name = NULL;

	return file;
}

static void
extendBufFile(BufFile *file)
{
	File		pfile;
	ResourceOwner oldowner;

	/* Be sure to associate the file with the BufFile's resource owner */
	oldowner = CurrentResourceOwner;
	CurrentResourceOwner = file->resowner;

	if (file->fileset == NULL)
		pfile = OpenTemporaryFile(file->isInterXact);
	else
		pfile = MakeNewSharedSegment(file, file->numFiles);

	Assert(pfile >= 0);

	CurrentResourceOwner = oldowner;

	file->files = (File *) repalloc(file->files,
									(file->numFiles + 1) * sizeof(File));
	file->files[file->numFiles] = pfile;
	file->numFiles++;
}

BufFile *
BufFileCreateTemp(bool interXact)
{
	BufFile    *file;
	File		pfile;

	/*
	 * Ensure that temp tablespaces are set up for OpenTemporaryFile to use.
	 * Possibly the caller will have done this already, but it seems useful to
	 * double-check here.  Failure to do this at all would result in the temp
	 * files always getting placed in the default tablespace, which is a
	 * pretty hard-to-detect bug.  Callers may prefer to do it earlier if they
	 * want to be sure that any required catalog access is done in some other
	 * resource context.
	 */
	PrepareTempTablespaces();

	pfile = OpenTemporaryFile(interXact);
	Assert(pfile >= 0);

	file = makeBufFile(pfile);
	file->isInterXact = interXact;

	return file;
}

static void
SharedSegmentName(char *name, const char *buffile_name, int segment)
{
	snprintf(name, MAXPGPATH, "%s.%d", buffile_name, segment);
}

static File
MakeNewSharedSegment(BufFile *buffile, int segment)
{
	char		name[MAXPGPATH];
	File		file;

	/*
	 * It is possible that there are files left over from before a crash
	 * restart with the same name.  In order for BufFileOpenShared() not to
	 * get confused about how many segments there are, we'll unlink the next
	 * segment number if it already exists.
	 */
	SharedSegmentName(name, buffile->name, segment + 1);
	SharedFileSetDelete(buffile->fileset, name, true);

	/* Create the new segment. */
	SharedSegmentName(name, buffile->name, segment);
	file = SharedFileSetCreate(buffile->fileset, name);

	/* SharedFileSetCreate would've errored out */
	Assert(file > 0);

	return file;
}

BufFile *
BufFileCreateShared(SharedFileSet *fileset, const char *name)
{
	BufFile    *file;

	file = makeBufFileCommon(1);
	file->fileset = fileset;
	file->name = pstrdup(name);
	file->files = (File *) palloc(sizeof(File));
	file->files[0] = MakeNewSharedSegment(file, 0);
	file->readOnly = false;

	return file;
}

BufFile *
BufFileOpenShared(SharedFileSet *fileset, const char *name, int mode)
{
	BufFile    *file;
	char		segment_name[MAXPGPATH];
	Size		capacity = 16;
	File	   *files;
	int			nfiles = 0;

	files = palloc(sizeof(File) * capacity);

	/*
	 * We don't know how many segments there are, so we'll probe the
	 * filesystem to find out.
	 */
	for (;;)
	{
		/* See if we need to expand our file segment array. */
		if (nfiles + 1 > capacity)
		{
			capacity *= 2;
			files = repalloc(files, sizeof(File) * capacity);
		}
		/* Try to load a segment. */
		SharedSegmentName(segment_name, name, nfiles);
		files[nfiles] = SharedFileSetOpen(fileset, segment_name, mode);
		if (files[nfiles] <= 0)
			break;
		++nfiles;

		CHECK_FOR_INTERRUPTS();
	}

	/*
	 * If we didn't find any files at all, then no BufFile exists with this
	 * name.
	 */
	if (nfiles == 0)
		ereport(ERROR,
				(errcode_for_file_access(),
				 errmsg("could not open temporary file \"%s\" from BufFile \"%s\": %m",
						segment_name, name)));

	file = makeBufFileCommon(nfiles);
	file->files = files;
	file->readOnly = (mode == O_RDONLY) ? true : false;
	file->fileset = fileset;
	file->name = pstrdup(name);

	return file;
}

void
BufFileDeleteShared(SharedFileSet *fileset, const char *name)
{
	char		segment_name[MAXPGPATH];
	int			segment = 0;
	bool		found = false;

	/*
	 * We don't know how many segments the file has.  We'll keep deleting
	 * until we run out.  If we don't manage to find even an initial segment,
	 * raise an error.
	 */
	for (;;)
	{
		SharedSegmentName(segment_name, name, segment);
		if (!SharedFileSetDelete(fileset, segment_name, true))
			break;
		found = true;
		++segment;

		CHECK_FOR_INTERRUPTS();
	}

	if (!found)
		elog(ERROR, "could not delete unknown shared BufFile \"%s\"", name);
}

void
BufFileExportShared(BufFile *file)
{
	/* Must be a file belonging to a SharedFileSet. */
	Assert(file->fileset != NULL);

	/* It's probably a bug if someone calls this twice. */
	Assert(!file->readOnly);

	BufFileFlush(file);
	file->readOnly = true;
}

class guiTypePanel : public guiBaseObject{

    public:

		//------------------------------------------------
		//override because of tab
		void updateBoundingBox(){
			hitArea.y = (int)boundingBox.y + tabHeight;
			boundingBox.height = hitArea.height;
		}

        //------------------------------------------------
        guiTypePanel(){
            currentXPos     = panelSpacing;
            currentYPos     = panelSpacing;
            spacingAmntX    = panelSpacing;
            spacingAmntY    = panelSpacing;

            columns.clear();
            columns.push_back(ofRectangle(20, 20, 30, 20));
            col = 0;
			bDrawLock = false;

			tabRect.x      = 0;
			tabRect.y      = 0;
			tabRect.width  = tabWidth;
			tabRect.height = tabHeight;
			bSelected = false;

			setGroupBgColor(255,255,255,255);
		}

        //------------------------------------------------
        void setup(string panelName, float defaultX = 20, float defaultY = 10){
            name = panelName;

            columns[0] = ofRectangle(defaultX, defaultY, 50, 20);

            //we don't want our panel flashing when we click :)
            bgColor.selected = bgColor.color;
            outlineColor.selected = outlineColor.color;
			updateText();

			tabRect.width = displayText.getTextWidth() + tabPadding*2;
			tabRect.height = displayText.getTextSingleLineHeight()*1.5f;
			groupBg.x = panelSpacing;
			groupBg.width = getWidth() - panelSpacing*2; 
			groupBg.y = panelSpacing;
        }

void addColumn(float minWidth){
            float colX = columns.back().x + columns.back().width + spacingAmntX;
            columns.push_back(ofRectangle(colX, 20, minWidth, 20));
        }

bool selectColumn(int which){
            col = ofClamp(which, 0, columns.size()-1);
            return true;
        }

void setElementSpacing(float spacingX, float spacingY){
            spacingAmntX = spacingX;
            spacingAmntY = spacingY;
        }

void setTabPosition(float tabX, float tabY){
			tabRect.x = tabX;
			tabRect.y = tabY;
		}

ofRectangle getTabRect(){
			return tabRect;
		}

virtual bool checkHit(float x, float y, bool isRelative){
            if(readOnly)return false;
            if( x >= hitArea.x && x <= hitArea.x + hitArea.width && y >= hitArea.y && y <= hitArea.y + hitArea.height){
                state = SG_STATE_SELECTED;

				float xx = x - boundingBox.x;
                float yy = y - boundingBox.y;

				if( xx  > lockRect.x && xx < lockRect.x + lockRect.width && yy > lockRect.y && yy < lockRect.y + lockRect.height ){
                    locked = !locked;
                }

                setSelected();
                updateGui(x, y, true, isRelative);

                if( !locked ){

                    float offsetX = x - hitArea.x;
                    float offsetY = y - hitArea.y;

                    for(int i = 0; i < children.size(); i++){
						children[i]->bTextEnterMode = false;
						children[i]->release();
					}

					bTextEnterMode = false;

                    for(int i = 0; i < children.size(); i++){
						children[i]->bTextEnterMode = bTextEnterMode;
                        children[i]->checkHit(offsetX, offsetY, isRelative);
						if (children[i]->bTextEnterMode){
							bTextEnterMode = true;
						}
                    }
                } else {
					resetChildren();
				}
                return true;
            }
            return false;
        }

virtual void keyPressed(int key){
			if( !locked ){
				for(int i = 0; i < children.size(); i++){
					//if (children[i]->state == SG_STATE_SELECTED) children[i]->keyPressed(key);
					children[i]->keyPressed(key);
				}
			}
		}

void updateGui(float x, float y, bool firstHit, bool isRelative){
            if( state == SG_STATE_SELECTED){

                float offsetX = 0;
                float offsetY = 0;

                if( isRelative ){
                    offsetX = x;
                    offsetY = y;
                }else{
                    offsetX = x - hitArea.x;
                    offsetY = y - hitArea.y;
                }

                if( !locked ){

                    for(int i = 0; i < children.size(); i++){
                        children[i]->updateGui(offsetX, offsetY, firstHit, isRelative);
                    }

                }
            }
        }

virtual void update(){
            updateText();

            lockRect.x          = boundingBox.width - (LOCK_WIDTH + spacingAmntX + LOCK_BORDER);
            lockRect.y          = spacingAmntY - LOCK_BORDER;
            lockRect.width      = LOCK_WIDTH + LOCK_BORDER * 2;
            lockRect.height     = LOCK_HEIGHT + LOCK_BORDER * 2;

            for(int i = 0; i < children.size(); i++){
                children[i]->update();
            }

            for(int i = 0; i < whichColumn.size(); i++){
                if( children[i]->boundingBox.x != columns[whichColumn[i]].x ){
                    float amntToShiftX = columns[whichColumn[i]].x - children[i]->boundingBox.x;

                    children[i]->hitArea.x += amntToShiftX;
                    children[i]->boundingBox.x += amntToShiftX;
                }
            }

			//reset y positions (if elements are added / dimensions changed)

			currentYPos = panelSpacing;
			for(int i = 0; i < children.size(); i++){
				children[i]->boundingBox.y = (int) currentYPos;
				currentYPos += children[i]->getHeight() + spacingAmntY;
			}

			//update group bg
			groupBg.height = 0;
			groupBg.width = getWidth() - panelSpacing*2; 
			if (groups.size() > 0) groupBg.height = panelSpacing + groups[groups.size()-1]->boundingBox.y + groups[groups.size()-1]->getHeight();
        }

