                            gpointer user_data)
{
  const CbUserIdentity *id = item;
  char *screen_name;
  GtkWidget *row = gtk_list_box_row_new ();
  GtkWidget *box = gtk_box_new (GTK_ORIENTATION_HORIZONTAL, 0);
