static void _draw_cursor_top(HLSPal *p,mBool erase)
{
	mPixbufDrawArrowUp(p->img,
		1 + APP_DRAW->col.hlspal_sel * _TOP_W + _TOP_W / 2 - 1, _TOP_H + 1,
		(erase)? MSYSCOL(FACE): MSYSCOL(TEXT));
}

static void _draw_cursor_pal(HLSPal *p,mBool erase)
{
	mPixbufBox(p->img,
		APP_DRAW->col.hlspal_palx * _PAL_W,
		_PAL_TOPY + APP_DRAW->col.hlspal_paly * _PAL_H,
		_PAL_W + 1, _PAL_H + 1,
		(erase)? 0: MSYSCOL(WHITE));
}

static void _draw_palette(HLSPal *p)
{
	mPixbuf *img = p->img;
	int ix,iy,x,y,c[3],hue;
	double ds;

	hue = APP_DRAW->col.hlspal_sel * _HUE_STEP_VAL;

	for(iy = 0, y = _PAL_TOPY + 1; iy < _PAL_YNUM; iy++, y += _PAL_H)
	{
		ds = _GET_S(iy);

		for(ix = 0, x = 1; ix < _PAL_XNUM; ix++, x += _PAL_W)
		{
			mHLStoRGB(hue, _GET_L(ix), ds, c);
			mPixbufFillBox(img, x, y, _PAL_W - 1, _PAL_H - 1, mRGBtoPix2(c[0], c[1], c[2]));
		}
	}
}

static void _draw_first(HLSPal *p)
{
	mPixbuf *img = p->img;
	int w = p->wg.hintW,i,n,h,c[3];

	//H 部分の枠

	mPixbufBox(img, 0, 0, w, _TOP_H, 0);

	for(i = _HUE_STEP - 1, n = _TOP_W; i; i--, n += _TOP_W)
		mPixbufLineV(img, n, 1, _TOP_H - 2, 0);

	//H 色

	for(i = 0, n = 1, h = 0; i < _HUE_STEP; i++, n += _TOP_W, h += _HUE_STEP_VAL)
	{
		mHLStoRGB(h, 0.5, 1.0, c);
		mPixbufFillBox(img, n, 1, _TOP_W - 1, _TOP_H - 2, mRGBtoPix2(c[0], c[1], c[2]));
	}

	//H とパレットの間

	mPixbufFillBox(img, 0, _TOP_H, w, _BETWEEN, MSYSCOL(FACE));

	//パレットの枠

	for(i = _PAL_XNUM + 1, n = 0; i; i--, n += _PAL_W)
		mPixbufLineV(img, n, _PAL_TOPY, _PAL_H * _PAL_YNUM + 1, 0);

	for(i = _PAL_YNUM + 1, n = _PAL_TOPY; i; i--, n += _PAL_H)
		mPixbufLineH(img, 0, n, _PAL_W * _PAL_XNUM + 1, 0);

	//パレット色、カーソル

	_draw_palette(p);
	_draw_cursor_top(p, FALSE);
	_draw_cursor_pal(p, FALSE);
}

static void _notify(HLSPal *p)
{
	uint32_t col;

	col = mHLStoRGB_pac(APP_DRAW->col.hlspal_sel * _HUE_STEP_VAL,
		_GET_L(APP_DRAW->col.hlspal_palx),
		_GET_S(APP_DRAW->col.hlspal_paly));

	/* DockColorPalette のタブ内容のメインコンテナに直接通知。
	 * 通知元は HLS パレットのタブ内容コンテナ。 */

	mWidgetAppendEvent_notify(MWIDGET_NOTIFYWIDGET_RAW, p->wg.parent, 0, col, 0);
}

static void _on_motion_top(HLSPal *p,int x)
{
	x = (x - 1) / _TOP_W;

	if(x < 0) x = 0;
	else if(x >= _HUE_STEP) x = _HUE_STEP - 1;

	if(x != APP_DRAW->col.hlspal_sel)
	{
		_draw_cursor_top(p, TRUE);

		APP_DRAW->col.hlspal_sel = x;

		_draw_cursor_top(p, FALSE);
		_draw_palette(p);

		mWidgetUpdate(M_WIDGET(p));

		_notify(p);
	}
}

static void _on_motion_palette(HLSPal *p,int x,int y)
{
	//パレット位置

	x = (x - 1) / _PAL_W;
	y = (y - _PAL_TOPY - 1) / _PAL_H;

	if(x < 0) x = 0; else if(x >= _PAL_XNUM) x = _PAL_XNUM - 1;
	if(y < 0) y = 0; else if(y >= _PAL_YNUM) y = _PAL_YNUM - 1;

	//前回位置と比較

	if(x != APP_DRAW->col.hlspal_palx || y != APP_DRAW->col.hlspal_paly)
	{
		//カーソル

		_draw_cursor_pal(p, TRUE);

		APP_DRAW->col.hlspal_palx = x;
		APP_DRAW->col.hlspal_paly = y;

		_draw_cursor_pal(p, FALSE);

		mWidgetUpdate(M_WIDGET(p));

		//色を通知

		_notify(p);
	}
}

static void _event_press(HLSPal *p,int x,int y)
{
	if(y < _PAL_TOPY)
	{
		//HUE

		p->fdrag = _DRAGF_TOP;

		_on_motion_top(p, x);
	}
	else
	{
		//パレット

		p->fdrag = _DRAGF_PALETTE;

		_on_motion_palette(p, x, y);
	}

	mWidgetGrabPointer(M_WIDGET(p));
}

static void _grab_release(HLSPal *p)
{
	if(p->fdrag)
	{
		p->fdrag = 0;
		mWidgetUngrabPointer(M_WIDGET(p));
	}
}

static int _event_handle(mWidget *wg,mEvent *ev)
{
	HLSPal *p = (HLSPal *)wg;

	switch(ev->type)
	{
		case MEVENT_POINTER:
			if(ev->pt.type == MEVENT_POINTER_TYPE_MOTION)
			{
				//移動

				if(p->fdrag == _DRAGF_PALETTE)
					_on_motion_palette(p, ev->pt.x, ev->pt.y);
				else if(p->fdrag == _DRAGF_TOP)
					_on_motion_top(p, ev->pt.x);
			}
			else if(ev->pt.type == MEVENT_POINTER_TYPE_PRESS)
			{
				//押し

				if(ev->pt.btt == M_BTT_LEFT && !p->fdrag)
					_event_press(p, ev->pt.x, ev->pt.y);
			}
			else if(ev->pt.type == MEVENT_POINTER_TYPE_RELEASE)
			{
				//離し

				if(ev->pt.btt == M_BTT_LEFT)
					_grab_release(p);
			}
			break;

		case MEVENT_FOCUS:
			if(ev->focus.bOut)
				_grab_release(p);
			break;
	}

	return 1;
}

namespace Inst {

class PlanGraph::BVEvaluator : public VAL::VisitController {
private:
// The BVEvaluator is going to own this bval.
	BoundedValue * bval;
	PlanGraph & pg;
	VAL::FastEnvironment * fenv;

	bool continuous;

public:
	BVEvaluator(PlanGraph & p,VAL::FastEnvironment * fe) : 
		bval(0), pg(p), fenv(fe), continuous(false) 
	{};
	~BVEvaluator() 
	{
		delete bval;
	};
	bool isContinuous() const {return continuous;};
	BoundedValue * getBV() 
	{
		BoundedValue * bv = bval;
		bval = 0;
		return bv;
	};
    virtual void visit_plus_expression(plus_expression * pe) 
    {
    	pe->getRHS()->visit(this);
		BoundedValue * br = bval;
		bval = 0;
		pe->getLHS()->visit(this);
		br = (*bval += br);
		if(br != bval)
		{
			delete bval;
			bval = br;
		};
    };
    virtual void visit_minus_expression(minus_expression * me) 
    {
		me->getRHS()->visit(this);
		BoundedValue * br = bval;
		bval = 0;
		me->getLHS()->visit(this);
		br = (*bval -= br);
		if(br != bval)
		{
			delete bval;
			bval = br;
		};
    };
    virtual void visit_mul_expression(mul_expression * pe) 
    {
    	pe->getRHS()->visit(this);
		BoundedValue * br = bval;
		bval = 0;
		pe->getLHS()->visit(this);
		if(continuous)
		{
			bval = br;
		}
		else
		{
			br = (*bval *= br);
			if(br != bval)
			{
				delete bval;
				bval = br;
			};
		};
    };
    virtual void visit_div_expression(div_expression * pe) 
    {
    	pe->getRHS()->visit(this);
		BoundedValue * br = bval;
		bval = 0;
		pe->getLHS()->visit(this);
		br = (*bval /= br);
		if(br != bval)
		{
			delete bval;
			bval = br;
		};
    };
    virtual void visit_uminus_expression(uminus_expression * um) 
    {
		um->getExpr()->visit(this);
		bval->negate();
    };
    virtual void visit_int_expression(int_expression * ie)
    {
		bval = new PointValue(ie->double_value());
    };
    virtual void visit_float_expression(float_expression * fe) 
    {
		bval = new PointValue(fe->double_value());
    };
    virtual void visit_special_val_expr(special_val_expr *) 
    {continuous = true;};
    virtual void visit_func_term(func_term * ft) 
    {
    	PNE pne(ft,fenv);
    	FluentEntry * fe = pg.fluents.find(instantiatedOp::getPNE(&pne));
		bval = fe?fe->getBV()->copy():new Undefined();
    };
};

class SpikeEvaluator : public VisitController {
private: 
	Spike<PropEntry> & spes;
	Spike<FluentEntry> & sfes;
	FastEnvironment* f;
	bool evaluation;
	PlanGraph & pg;

	pred_symbol * equality;
public:
	SpikeEvaluator(PlanGraph & p,Spike<PropEntry> & s1,Spike<FluentEntry> & s2, FastEnvironment * fe): 
		spes(s1), sfes(s2), f(fe), evaluation(true), pg(p),
		equality(current_analysis->pred_tab.symbol_probe("=")) {
	}

	virtual void visit_simple_goal(simple_goal * s){		
		if(EPS(s->getProp()->head)->getParent() == this->equality){
			evaluation = ((*f)[s->getProp()->args->front()] == 
						(*f)[s->getProp()->args->back()]);


			if(s->getPolarity() == E_NEG)
			{
				evaluation = !evaluation;
			};
			return;
		}
		else {
			Literal e(s->getProp(),f);
			Literal* lptr = instantiatedOp::getLiteral(& e);
			PropEntry* eid = spes.find(lptr);
			if(eid){
				if(s->getPolarity() == E_NEG){
					evaluation = eid->gotDeleters();
				}
				else {
					evaluation = eid->gotAchievers();
				}
			}
			else {
				if(s->getPolarity() == E_NEG){
					evaluation = true;

				}
				else {
					evaluation = false;
				}
			};
		};

	};

	bool getEvaluation() const {return evaluation;};	

	virtual void visit_qfied_goal(qfied_goal * qg){
		cout << "Not currently handling quantified goals\n";
	}
	virtual void visit_conj_goal(conj_goal * c){
		for(goal_list::const_iterator i = c->getGoals()->begin();
			i != c->getGoals()->end();++i)
		{
			(*i)->visit(this);
			if(!evaluation){
				return;
			}
		}
	};
	virtual void visit_disj_goal(disj_goal * c){	
		cout << "Not dealing with disjunctive goals\n";
	};
	virtual void visit_timed_goal(timed_goal * t){
		cout << "Not currently handling timed goals\n";
	}
	virtual void visit_imply_goal(imply_goal * ig){	
		cout << "Not dealing with implications\n";
	};

	virtual void visit_neg_goal(neg_goal * ng){
		ng->getGoal()->visit(this);
		evaluation = !evaluation;
	}
	virtual void visit_comparison(comparison * c){
		// Evaluate the parts and combine according to 
		// rearrangement then do the comparison with a 
		// bounds check.
		PlanGraph::BVEvaluator bve(pg,f);
		c->getLHS()->visit(&bve);
		BoundedValue * bvl = bve.getBV();
		c->getRHS()->visit(&bve);
		BoundedValue * bvr = bve.getBV();
		BoundedValue * bvres = (*bvl -= bvr);
		switch(c->getOp())
		{
			case E_GREATER:
				evaluation = !bvres->gotUB() || bvres->getUB() > 0;
				break;
			case E_GREATEQ:
				evaluation = !bvres->gotUB() || bvres->getUB() >= 0;
				break;
			case E_LESS:
				evaluation = !bvres->gotLB() || bvres->getLB() < 0;
				break;
			case E_LESSEQ:
				evaluation = !bvres->gotLB() || bvres->getLB() <= 0;
				break;
			case E_EQUALS:
				evaluation = (!bvres->gotLB() || bvres->getLB() <= 0) &&
								(!bvres->gotUB() || bvres->getUB() >= 0);
				break;
			default:
				break;
		};

	}

	virtual void visit_action(action * op){	
		op->precondition->visit(this);
	};
	virtual void visit_event(event * e){	
		e->precondition->visit(this);
	};
	virtual void visit_process(process * p){	
		p->precondition->visit(this);
	};
	virtual void visit_durative_action(durative_action * da) {
		cout << "Not dealing with duratives\n";
	};
};

class SpikeSupporter : public VisitController {
private: 
	Spike<PropEntry> & spes;
	Spike<FluentEntry> & sfes;
	FastEnvironment* f;
	ActEntry * ae;

	GraphFactory * myFac;

	bool context;

	pred_symbol * equality;
public:
	SpikeSupporter(Spike<PropEntry> & s1,Spike<FluentEntry> & s2, FastEnvironment * fe,ActEntry * a,GraphFactory * mf): 
		spes(s1), sfes(s2), f(fe), ae(a), myFac(mf), context(true),
		equality(current_analysis->pred_tab.symbol_probe("=")) {
	}

	virtual void visit_simple_goal(simple_goal * s){		
		if(EPS(s->getProp()->head)->getParent() != this->equality){
			Literal e(s->getProp(),f);
			Literal* lptr = instantiatedOp::getLiteral(& e);
			PropEntry* eid = spes.findInAll(lptr);
			if(eid){
				if(context && s->getPolarity() == E_NEG ||
					!context && s->getPolarity()==E_POS){
					ae->addSupportedByNeg(eid);
					cout << "Support by neg: " << *ae << " with " << *eid << "\n";
				}
				else {
					ae->addSupportedBy(eid);
				}
			}
			else {
				eid=myFac->makePropEntry(lptr);
			// make the entry for eid

				ae->addSupportedByNeg(eid);
				spes.insertAbsentee(eid);	


			};
		};

	};

	virtual void visit_conj_goal(conj_goal * c){
		for(goal_list::const_iterator i = c->getGoals()->begin();
			i != c->getGoals()->end();++i)
		{
			(*i)->visit(this);
		}
	};

	virtual void visit_comparison(comparison * c){
		//cout << "Er....what?\n";
	}

	virtual void visit_neg_goal(neg_goal * ng)
	{
		context = !context;
		ng->getGoal()->visit(this);
	};

	virtual void visit_action(action * op){	
		op->precondition->visit(this);
	};
	virtual void visit_event(event * e){	
		e->precondition->visit(this);
	};
	virtual void visit_process(process * p){	
		p->precondition->visit(this);
	};
	virtual void visit_durative_action(durative_action * da) {
