BoundedValue * BoundedInterval::operator+=(const BoundedValue * bv)
{
	if(!finitelbnd || !bv->gotLB())
	{
		finitelbnd = false;
	}
	else
	{
		lbnd += bv->getLB();
	};
	if(!finiteubnd || !bv->gotUB())
	{
		finiteubnd = false;
	}
	else
	{
		ubnd += bv->getUB();
	};
	return this;
}

