void DurationHolder::readDurations(const string & nm)
{
	std::ifstream dursFile(nm.c_str());
	string a;
	string ax;
	string s;
	dursFile >> a;
	ax = a;
	vector<int> args;
	while(!dursFile.eof())
	{
		dursFile >> s;
		if(s == "=")
		{
			relevantArgs[a] = args;
			args.clear();
			double d;
			dursFile >> d;
			dursFor[ax] = new DurationConstraint(new PointValue(d));
			dursFile >> a;
			ax = a;
		}
		else
		{
			int arg;
			dursFile >> arg;
			args.push_back(arg);
			ax += " ";
			ax += s;
		};
	};	
}

