void GLFWApp::preprocess_input(InputEvent & event)
{
    if (event.type == InputEvent::MOUSE)
    {
        if (event.is_down()) isDragging = true;
        else if (event.is_up()) isDragging = false;
    }
    event.drag = isDragging;
    on_input(event);
}

