Logical FATR srtdb_print_(const Integer *handle, const Logical *print_values)
{
  int hbuf = (int) *handle;
  int pbuf = (int) *print_values;

  if (srtdb_print(hbuf, pbuf))
    return FORTRAN_TRUE;
