bool catch_up_in_lu_tableau(const vector<unsigned> & trace_of_basis_change, const vector<int> & basis_heading) {
        lp_assert(r_basis_is_OK());
        // the queues of delayed indices
        std::queue<unsigned> entr_q, leav_q;
        for (unsigned i = 0; i < trace_of_basis_change.size(); i+= 2) {
            unsigned entering = trace_of_basis_change[i];
            unsigned leaving = trace_of_basis_change[i+1];
            bool good_e = basis_heading[entering] >= 0 && m_r_solver.m_basis_heading[entering] < 0;
            bool good_l = basis_heading[leaving] < 0 && m_r_solver.m_basis_heading[leaving] >= 0;
            if (!good_e && !good_l) continue;
            if (good_e && !good_l) {
                while (!leav_q.empty() && m_r_solver.m_basis_heading[leav_q.front()] < 0)
                    leav_q.pop();
                if (!leav_q.empty()) {
                    leaving = leav_q.front();
                    leav_q.pop();
                } else {
                    entr_q.push(entering);
                    continue;
                }
            } else if (!good_e && good_l) {
                while (!entr_q.empty() && m_r_solver.m_basis_heading[entr_q.front()] >= 0)
                    entr_q.pop();
                if (!entr_q.empty()) {
                    entering = entr_q.front();
                    entr_q.pop();
                } else {
                    leav_q.push(leaving);
                    continue;
                }
            }
            lp_assert(m_r_solver.m_basis_heading[entering] < 0);
            lp_assert(m_r_solver.m_basis_heading[leaving] >= 0);
            m_r_solver.change_basis_unconditionally(entering, leaving);
            if(!m_r_solver.pivot_column_tableau(entering, m_r_solver.m_basis_heading[entering])) {
                // unroll the last step
                m_r_solver.change_basis_unconditionally(leaving, entering);
#ifdef Z3DEBUG
                bool t =
#endif
                    m_r_solver.pivot_column_tableau(leaving, m_r_solver.m_basis_heading[leaving]);
#ifdef Z3DEBUG
                lp_assert(t);
#endif 
                return false;
            }
        }
        lp_assert(r_basis_is_OK());
        return true;
    }

void solve_on_signature(const lar_solution_signature & signature, const vector<unsigned> & changes_of_basis) {
        SASSERT(!settings().use_tableau());
        if (m_r_solver.m_factorization == nullptr) {
            for (unsigned j = 0; j < changes_of_basis.size(); j+=2) {
                unsigned entering = changes_of_basis[j];
                unsigned leaving = changes_of_basis[j + 1];
                m_r_solver.change_basis_unconditionally(entering, leaving);
            }
            init_factorization(m_r_solver.m_factorization, m_r_A, m_r_basis, settings());
        } else {
            catch_up_in_lu(changes_of_basis, m_d_solver.m_basis_heading, m_r_solver);
        }

        if (no_r_lu()) { // it is the case where m_d_solver gives a degenerated basis, we need to roll back
            catch_up_in_lu_in_reverse(changes_of_basis, m_r_solver);
            m_r_solver.find_feasible_solution();
            m_d_basis = m_r_basis;
            m_d_heading = m_r_heading;
            m_d_nbasis = m_r_nbasis;
            delete m_d_solver.m_factorization;
            m_d_solver.m_factorization = nullptr;
        } else {
            prepare_solver_x_with_signature(signature, m_r_solver);
            m_r_solver.start_tracing_basis_changes();
            m_r_solver.find_feasible_solution();
            if (settings().get_cancel_flag())
                return;
            m_r_solver.stop_tracing_basis_changes();
            // and now catch up in the double solver
            lp_assert(m_r_solver.total_iterations() >= m_r_solver.m_trace_of_basis_change_vector.size() /2);
            catch_up_in_lu(m_r_solver.m_trace_of_basis_change_vector, m_r_solver.m_basis_heading, m_d_solver);
        }
    }

void create_double_matrix(static_matrix<double, double> & A) {
        for (unsigned i = 0; i < m_r_A.row_count(); i++) {
            auto & row = m_r_A.m_rows[i];
            for (row_cell<mpq> & c : row) {
                A.add_new_element(i, c.var(), c.coeff().get_double());
            }
        }
    }

    void fill_basis_d(
                      vector<unsigned>& basis_d,
                      vector<int>& heading_d,
                      vector<unsigned>& nbasis_d){
        basis_d = m_r_basis;
        heading_d = m_r_heading;
        nbasis_d = m_r_nbasis;
    }

    template <typename L, typename K>
    void extract_signature_from_lp_core_solver(const lp_primal_core_solver<L, K> & solver, lar_solution_signature & signature) {
        signature.clear();
        lp_assert(signature.size() == 0);
        for (unsigned j = 0; j < solver.m_basis_heading.size(); j++) {
            if (solver.m_basis_heading[j] < 0) {
                signature[j] = solver.get_non_basic_column_value_position(j);
            }
        }
    }

    void get_bounds_for_double_solver() {
        unsigned n = m_n();
        m_d_lower_bounds.resize(n);
        m_d_upper_bounds.resize(n);
        double delta = find_delta_for_strict_boxed_bounds().get_double();
        if (delta > 0.000001)
            delta = 0.000001;
        for (unsigned j = 0; j < n; j++) {
            if (lower_bound_is_set(j)) {
                const auto & lb = m_r_solver.m_lower_bounds[j];
                m_d_lower_bounds[j] = lb.x.get_double() + delta * lb.y.get_double();
            }
            if (upper_bound_is_set(j)) {
                const auto & ub = m_r_solver.m_upper_bounds[j];
                m_d_upper_bounds[j] = ub.x.get_double() + delta * ub.y.get_double();
                lp_assert(!lower_bound_is_set(j) || (m_d_upper_bounds[j] >= m_d_lower_bounds[j]));
            }
        }
    }

    void scale_problem_for_doubles(
                        static_matrix<double, double>& A,        
                        vector<double> & lower_bounds,
                        vector<double> & upper_bounds) {
        vector<double> column_scale_vector;
        vector<double> right_side_vector(A.column_count());
        settings().reps_in_scaler = 5;
        scaler<double, double > scaler(right_side_vector,
                                       A,
                                       settings().scaling_minimum,
                                       settings().scaling_maximum,
                                       column_scale_vector,
                                       settings());
        if (! scaler.scale()) {
            // the scale did not succeed, unscaling
            A.clear();
            create_double_matrix(A);
        } else {
            for (unsigned j = 0; j < A.column_count(); j++) {
                if (m_r_solver.column_has_upper_bound(j)) {
                    upper_bounds[j] /= column_scale_vector[j];
                }
                if (m_r_solver.column_has_lower_bound(j)) {
                    lower_bounds[j] /= column_scale_vector[j];
                }
            }
        }

    }
    // returns the trace of basis changes
    vector<unsigned> find_solution_signature_with_doubles(lar_solution_signature & signature) {
        if (m_d_solver.m_factorization == nullptr || m_d_solver.m_factorization->get_status() != LU_status::OK) {
            vector<unsigned> ret;
            return ret;
        }
        get_bounds_for_double_solver();

        extract_signature_from_lp_core_solver(m_r_solver, signature);
        prepare_solver_x_with_signature(signature, m_d_solver);
        m_d_solver.start_tracing_basis_changes();
        m_d_solver.find_feasible_solution();
        if (settings().get_cancel_flag())
            return vector<unsigned>();

        m_d_solver.stop_tracing_basis_changes();
        extract_signature_from_lp_core_solver(m_d_solver, signature);
        return m_d_solver.m_trace_of_basis_change_vector;
    }


    bool lower_bound_is_set(unsigned j) const {
        switch (m_column_types[j]) {
        case column_type::free_column:
        case column_type::upper_bound:
            return false;
        case column_type::lower_bound:
        case column_type::boxed:
        case column_type::fixed:
            return true;
        default:
            lp_assert(false);
        }
        return false;
    }

    bool upper_bound_is_set(unsigned j) const {
        switch (m_column_types[j]) {
        case column_type::free_column:
        case column_type::lower_bound:
            return false;
        case column_type::upper_bound:
        case column_type::boxed:
        case column_type::fixed:
            return true;
        default:
            lp_assert(false);
        }
        return false;
    }

    void update_delta(mpq& delta, numeric_pair<mpq> const& l, numeric_pair<mpq> const& u) const {
        lp_assert(l <= u);
        if (l.x < u.x && l.y > u.y) {
            mpq delta1 = (u.x - l.x) / (l.y - u.y);
            if (delta1 < delta) {
                delta = delta1;
            }
        }
        lp_assert(l.x + delta * l.y <= u.x + delta * u.y);
    }


    mpq find_delta_for_strict_boxed_bounds() const{
        mpq delta = numeric_traits<mpq>::one();
        for (unsigned j = 0; j < m_r_A.column_count(); j++ ) {
            if (m_column_types()[j] != column_type::boxed)
                continue;
            update_delta(delta, m_r_lower_bounds[j], m_r_upper_bounds[j]);
        }
        return delta;
    }

mpq find_delta_for_strict_bounds(const mpq & initial_delta) const{
        mpq delta = initial_delta;
        for (unsigned j = 0; j < m_r_A.column_count(); j++ ) {
            if (lower_bound_is_set(j))
                update_delta(delta, m_r_lower_bounds[j], m_r_x[j]);
            if (upper_bound_is_set(j))
                update_delta(delta, m_r_x[j], m_r_upper_bounds[j]);
        }
        return delta;
    }

void init_column_row_nz_for_r_solver() {
        m_r_solver.init_column_row_non_zeroes();
    }

bool column_is_fixed(unsigned j) const {
        return m_column_types()[j] == column_type::fixed ||
            ( m_column_types()[j] == column_type::boxed &&
              m_r_solver.m_lower_bounds[j] == m_r_solver.m_upper_bounds[j]);
    }

bool column_is_free(unsigned j) const {
        return m_column_types()[j] == column_type::free_column;
    }

namespace Kyra {

TextDisplayer_SegaCD::TextDisplayer_SegaCD(EoBEngine *engine, Screen_EoB *scr) : TextDisplayer_rpg(engine, scr), _engine(engine), _screen(scr), _renderer(scr->sega_getRenderer()),
	_curDim(0), _textColor(0xFF), _curPosY(0), _curPosX(0) {
	assert(_renderer);
	_msgRenderBufferSize = 320 * 48;
	_msgRenderBuffer = new uint8[_msgRenderBufferSize];
	memset(_msgRenderBuffer, 0, _msgRenderBufferSize);
}

void TextDisplayer_SegaCD::printDialogueText(int id, const char *string1, const char *string2) {
	if (string1 && string2) {
		_engine->runDialogue(id, 2, 2, string1, string2);
	} else {
		_screen->hideMouse();
		_engine->seq_segaPlaySequence(id);
		_screen->showMouse();
	}
}

void TextDisplayer_SegaCD::printDialogueText(const char *str, bool wait) {
	int cs = _screen->setFontStyles(Screen::FID_8_FNT, _vm->gameFlags().lang == Common::JA_JPN ? Font::kStyleFixedWidth : Font::kStyleFat | Font::kStyleForceTwoByte);
	clearDim(_curDim);

	if (wait) {
		printShadedText(str, 32, 12);
		_engine->resetSkipFlag();
		_renderer->render(0);
		_screen->updateScreen();
		_engine->delay(500);
	} else {
		printShadedText(str, 0, 0);
		_renderer->render(0);
		_screen->updateScreen();
	}

	_screen->setFontStyles(Screen::FID_8_FNT, cs);
}

void TextDisplayer_SegaCD::printShadedText(const char *str, int x, int y, int textColor, int shadowColor, int pitchW, int pitchH, int marginRight, bool screenUpdate) {
	const ScreenDim *s = &_dimTable[_curDim];
	if (x == -1)
		x = s->sx;
	if (y == -1)
		y = s->sy;
	if (textColor == -1)
		textColor = s->unk8;
	if (shadowColor == -1)
		shadowColor = 0;
	if (pitchW == -1)
		pitchW = s->w;
	if (pitchH == -1)
		pitchH = s->h;

	_screen->setTextMarginRight(pitchW - marginRight);
	_screen->printShadedText(str, x, y, textColor, 0, shadowColor, pitchW >> 3);

	if (!screenUpdate)
		return;

	if (s->unkE) {
		for (int i = 0; i < (pitchH >> 3); ++i)
			_screen->sega_loadTextBufferToVRAM(i * (pitchW << 2), ((s->unkC & 0x7FF) + i * s->unkE) << 5, pitchW << 2);
	} else {
		_screen->sega_loadTextBufferToVRAM(0, (s->unkC & 0x7FF) << 5, (pitchW * pitchH) >> 1);
	}
}

int TextDisplayer_SegaCD::clearDim(int dim) {
	int res = _curDim;
	_curDim = dim;
	_curPosY = _curPosX = 0;
	const ScreenDim *s = &_dimTable[dim];
	_renderer->memsetVRAM((s->unkC & 0x7FF) << 5, s->unkA, (s->w * s->h) >> 1);
	_screen->sega_clearTextBuffer(s->unkA);
	memset(_msgRenderBuffer, 0, _msgRenderBufferSize);
	return res;
}

void TextDisplayer_SegaCD::displayText(char *str, ...) {
	_screen->sega_setTextBuffer(_msgRenderBuffer, _msgRenderBufferSize);
	int cs = _screen->setFontStyles(Screen::FID_8_FNT, _vm->gameFlags().lang == Common::JA_JPN ? Font::kStyleFixedWidth : Font::kStyleFat | Font::kStyleForceTwoByte);
	char tmp[3] = "  ";
	int posX = _curPosX;
	bool updated = false;

	va_list args;
	va_start(args, str);
	int tc = va_arg(args, int);
	va_end(args);

	if (tc != -1)
		SWAP(_textColor, tc);

	for (const char *pos = str; *pos; updated = false) {
		uint8 cmd = fetchCharacter(tmp, pos);

		if (_dimTable[_curDim].h < _curPosY + _screen->getFontHeight()) {
			_curPosY -= _screen->getFontHeight();
			linefeed();
		}

		if (cmd == 6) {
			_textColor = (uint8)*pos++;
		} else if (cmd == 2) {
			pos++;
		} else if (cmd == 13) {
			_curPosX = 0;
			_curPosY += _screen->getFontHeight();
		} else if (cmd == 9) {
			_curPosX = posX;
			_curPosY += _screen->getFontHeight();
		} else {
			if (((tmp[0] == ' ' || (tmp[0] == '\x81' && tmp[1] == '\x40')) && (_curPosX + _screen->getTextWidth(tmp) + _screen->getTextWidth((const char*)(pos), true) >= _dimTable[_curDim].w)) || (_curPosX + _screen->getTextWidth(tmp) >= _dimTable[_curDim].w)) {
				// Skip space at the beginning of the new line
				if (tmp[0] == ' ' || (tmp[0] == '\x81' && tmp[1] == '\x40'))
					fetchCharacter(tmp, pos);

				_curPosX = 0;
				_curPosY += _screen->getFontHeight();
				if (_dimTable[_curDim].h < _curPosY + _screen->getFontHeight()) {
					_curPosY -= _screen->getFontHeight();
					linefeed();
				}
			}

			printShadedText(tmp, _curPosX, _curPosY, _textColor);
			_curPosX += _screen->getTextWidth(tmp);
			updated = true;
		}
	}

	if (!updated)
		printShadedText("", _curPosX, _curPosY, _textColor);

	if (tc != -1)
		SWAP(_textColor, tc);

	_renderer->render(Screen_EoB::kSegaRenderPage);
	_screen->setFontStyles(Screen::FID_8_FNT, cs);
	_screen->copyRegion(8, 176, 8, 176, 280, 24, Screen_EoB::kSegaRenderPage, 0, Screen::CR_NO_P_CHECK);
	_screen->sega_setTextBuffer(0, 0);
}

uint8 TextDisplayer_SegaCD::fetchCharacter(char *dest, const char *&src) {
	uint8 c = (uint8)*src++;

	if (c <= (uint8)'\r') {
		dest[0] = '\0';
		return c;
	}

	dest[0] = (char)c;
	dest[1] = (c <= 0x7F || (c >= 0xA1 && c <= 0xDF)) ? '\0' : *src++;

	return 0;
}

void TextDisplayer_SegaCD::linefeed() {
	copyTextBufferLine(_screen->getFontHeight(), 0, (_dimTable[_curDim].h & ~7) - _screen->getFontHeight(), _dimTable[_curDim].w >> 3);
	clearTextBufferLine(_screen->getFontHeight(), _screen->getFontHeight(), _dimTable[_curDim].w >> 3, _dimTable[_curDim].unkA);
}

void TextDisplayer_SegaCD::clearTextBufferLine(uint16 y, uint16 lineHeight, uint16 pitch, uint8 col) {
	uint32 *dst = (uint32*)(_msgRenderBuffer + (((y >> 3) * pitch) << 5) + ((y & 7) << 2));
	int ln = y;
	uint32 c = col | (col << 8) | (col << 16) | (col << 24);
	while (lineHeight--) {
		uint32 *dst2 = dst;
		for (uint16 w = pitch; w; --w) {
			*dst = c;
			dst += 8;
		}
		dst = dst2 + 1;
		if (((++ln) & 7) == 0)
			dst += ((pitch - 1) << 3);
	}
}

void TextDisplayer_SegaCD::copyTextBufferLine(uint16 srcY, uint16 dstY, uint16 lineHeight, uint16 pitch) {
	uint32 *src = (uint32*)(_msgRenderBuffer + (((srcY >> 3) * pitch) << 5) + ((srcY & 7) << 2));
	uint32 *dst = (uint32*)(_msgRenderBuffer + (((dstY >> 3) * pitch) << 5) + ((dstY & 7) << 2));
	int src_ln = srcY;
	int dst_ln = dstY;

	while (lineHeight--) {
		uint32 *src2 = src;
		uint32 *dst2 = dst;

		for (uint16 w = pitch; w; --w) {
			*dst = *src;
			src += 8;
			dst += 8;
		}

		src = src2 + 1;
		dst = dst2 + 1;

		if (((++dst_ln) & 7) == 0)
			dst += ((pitch - 1) << 3);
		if (((++src_ln) & 7) == 0)
			src += ((pitch - 1) << 3);
	}
}

void *sqliteMalloc_(int n, char *zFile, int line){
  void *p;
  int *pi;
  int k;
  if( sqlite_iMallocFail>=0 ){
    sqlite_iMallocFail--;
    if( sqlite_iMallocFail==0 ){
      sqlite_malloc_failed++;
#if MEMORY_DEBUG>1
      fprintf(stderr,"**** failed to allocate %d bytes at %s:%d\n",
              n, zFile,line);
#endif
      sqlite_iMallocFail--;
      return 0;
    }
  }
  if( n==0 ) return 0;
  k = (n+sizeof(int)-1)/sizeof(int);
  pi = malloc( (3+k)*sizeof(int));
  if( pi==0 ){
    sqlite_malloc_failed++;
    return 0;
  }
  sqlite_nMalloc++;
  pi[0] = 0xdead1122;
  pi[1] = n;
  pi[k+2] = 0xdead3344;
  p = &pi[2];
  memset(p, 0, n);
#if MEMORY_DEBUG>1
  fprintf(stderr,"malloc %d bytes at 0x%x from %s:%d\n", n, (int)p, zFile,line);
#endif
  return p;
}

void sqliteFree_(void *p, char *zFile, int line){
  if( p ){
    int *pi, k, n;
    pi = p;
    pi -= 2;
    sqlite_nFree++;
    if( pi[0]!=0xdead1122 ){
      fprintf(stderr,"Low-end memory corruption at 0x%x\n", (int)p);
      return;
    }
    n = pi[1];
    k = (n+sizeof(int)-1)/sizeof(int);
    if( pi[k+2]!=0xdead3344 ){
      fprintf(stderr,"High-end memory corruption at 0x%x\n", (int)p);
      return;
    }
    memset(pi, 0xff, (k+3)*sizeof(int));
#if MEMORY_DEBUG>1
    fprintf(stderr,"free %d bytes at 0x%x from %s:%d\n", n, (int)p, zFile,line);
#endif
    free(pi);
  }
}

void *sqliteRealloc_(void *oldP, int n, char *zFile, int line){
  int *oldPi, *pi, k, oldN, oldK;
  void *p;
  if( oldP==0 ){
    return sqliteMalloc_(n,zFile,line);
  }
  if( n==0 ){
    sqliteFree_(oldP,zFile,line);
    return 0;
  }
  oldPi = oldP;
  oldPi -= 2;
  if( oldPi[0]!=0xdead1122 ){
    fprintf(stderr,"Low-end memory corruption in realloc at 0x%x\n", (int)p);
    return 0;
  }
  oldN = oldPi[1];
  oldK = (oldN+sizeof(int)-1)/sizeof(int);
  if( oldPi[oldK+2]!=0xdead3344 ){
    fprintf(stderr,"High-end memory corruption in realloc at 0x%x\n", (int)p);
    return 0;
  }
  k = (n + sizeof(int) - 1)/sizeof(int);
  pi = malloc( (k+3)*sizeof(int) );
  if( pi==0 ){
    sqlite_malloc_failed++;
    return 0;
  }
  pi[0] = 0xdead1122;
  pi[1] = n;
  pi[k+2] = 0xdead3344;
  p = &pi[2];
  memcpy(p, oldP, n>oldN ? oldN : n);
  if( n>oldN ){
    memset(&((char*)p)[oldN], 0, n-oldN);
  }
  memset(oldPi, 0, (oldK+3)*sizeof(int));
  free(oldPi);
#if MEMORY_DEBUG>1
  fprintf(stderr,"realloc %d to %d bytes at 0x%x to 0x%x at %s:%d\n", oldN, n,
    (int)oldP, (int)p, zFile, line);
#endif
  return p;
}

void sqliteStrRealloc(char **pz){
  char *zNew;
  if( pz==0 || *pz==0 ) return;
  zNew = malloc( strlen(*pz) + 1 );
  if( zNew==0 ){
    sqlite_malloc_failed++;
    sqliteFree(*pz);
    *pz = 0;
  }
  strcpy(zNew, *pz);
  sqliteFree(*pz);
  *pz = zNew;
}

char *sqliteStrDup_(const char *z, char *zFile, int line){
  char *zNew;
  if( z==0 ) return 0;
  zNew = sqliteMalloc_(strlen(z)+1, zFile, line);
  if( zNew ) strcpy(zNew, z);
  return zNew;
}

char *sqliteStrNDup_(const char *z, int n, char *zFile, int line){
  char *zNew;
  if( z==0 ) return 0;
  zNew = sqliteMalloc_(n+1, zFile, line);
  if( zNew ){
    memcpy(zNew, z, n);
    zNew[n] = 0;
  }
  return zNew;
}

void *sqliteMalloc(int n){
  void *p = malloc(n);
  if( p==0 ){
    sqlite_malloc_failed++;
    return 0;
  }
  memset(p, 0, n);
  return p;
}

void sqliteFree(void *p){
  if( p ){
    free(p);
  }
}

void *sqliteRealloc(void *p, int n){
  void *p2;
  if( p==0 ){
    return sqliteMalloc(n);
  }
  if( n==0 ){
    sqliteFree(p);
    return 0;
  }
  p2 = realloc(p, n);
  if( p2==0 ){
    sqlite_malloc_failed++;
  }
  return p2;
}

char *sqliteStrDup(const char *z){
  char *zNew;
  if( z==0 ) return 0;
  zNew = sqliteMalloc(strlen(z)+1);
  if( zNew ) strcpy(zNew, z);
  return zNew;
}

static ib_status_t modlua_append_searchprefix(
    ib_engine_t *ib,
    lua_State   *L,
    const char  *prefix
)
{
    assert(ib != NULL);
    assert(L != NULL);
    assert(prefix != NULL);

    /* This is the search pattern that is appended to each element of
     * lua_search_paths and then added to the Lua runtime package.path
     * global variable. */
    static const char *lua_file_pattern = "?.lua";
    static const char *lua_cfile_pattern = "?.so";

    ib_mpool_lite_t *mp;
    ib_mm_t          mm;
    ib_status_t      rc;

    char            *path = NULL; /* Tmp string to build a search path. */
    char            *cpath = NULL; /* Tmp string to build a search path. */

    rc = ib_mpool_lite_create(&mp);
    if (rc != IB_OK) {
        return rc;
    }

    mm = ib_mm_mpool_lite(mp);

    /* Strlen + 2. One for \0 and 1 for the path separator. */
    path = ib_mm_alloc(mm, strlen(prefix) + strlen(lua_file_pattern) + 2);
    if (path == NULL) {
        rc = IB_EALLOC;
        goto cleanup;
    }

    cpath = ib_mm_alloc(mm, strlen(prefix) + strlen(lua_cfile_pattern) + 2);
    if (cpath == NULL) {
        rc = IB_EALLOC;
        goto cleanup;
    }

    strcpy(path, prefix);
    strcpy(path + strlen(path), "/");
    strcpy(path + strlen(path), lua_file_pattern);
    ib_lua_add_require_path(ib, L, path);

    strcpy(cpath, prefix);
    strcpy(cpath + strlen(cpath), "/");
    strcpy(cpath + strlen(cpath), lua_cfile_pattern);
    ib_lua_add_require_cpath(ib, L, cpath);

cleanup:
    ib_mpool_lite_destroy(mp);
    return rc;
}

static ib_status_t modlua_setup_searchpath(ib_engine_t *ib, lua_State *L)
{
    /* Null terminated list of search paths. */
    const char    *lua_search_paths[4];
    ib_status_t    rc;
    ib_core_cfg_t *corecfg = NULL;

    rc = ib_core_context_config(ib_context_main(ib), &corecfg);
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to retrieve core module configuration.");
        return rc;
    }

    /* Initialize the search paths list. */
    lua_search_paths[0] = LUA_BASE_PATH_STR;
    lua_search_paths[1] = corecfg->module_base_path;
    lua_search_paths[2] = corecfg->rule_base_path;
    lua_search_paths[3] = NULL;

    for (const char **path = lua_search_paths; *path != NULL; ++path)
    {
        rc = modlua_append_searchprefix(ib, L, *path);
        if (rc != IB_OK) {
            return rc;
        }
    }

    return IB_OK;
}

static ib_status_t modlua_preload(ib_engine_t *ib, lua_State *L)
{

    ib_status_t rc;

    const char *lua_preloads[][2] = { { "waggle", "ironbee/waggle" },
                                      { "ibconfig", "ironbee/config" },
                                      { "ffi", "ffi" },
                                      { "ibapi", "ironbee/api" },
                                      { "modlua", "ironbee/module" },
                                      { NULL, NULL } };

    for (int i = 0; lua_preloads[i][0] != NULL; ++i)
    {
        rc = ib_lua_require(ib, L, lua_preloads[i][0], lua_preloads[i][1]);
        if (rc != IB_OK)
        {
            ib_log_error(ib,
                "Failed to load mode \"%s\" into \"%s\".",
                lua_preloads[i][1],
                lua_preloads[i][0]);
            return rc;
        }
    }

    return IB_OK;
}

static ib_status_t modlua_newstate(
    ib_engine_t   *ib,
    modlua_cfg_t  *cfg,
    lua_State    **Lout
)
{
    lua_State   *L;
    ib_status_t  rc;
    int          lua_rc;

    L = luaL_newstate();
    if (L == NULL) {
        ib_log_error(ib, "Failed to initialize lua module.");
        return IB_EUNKNOWN;
    }

    luaL_openlibs(L);

    /* Inject some constants so we know we are in the IronBee Lua Module. */
    lua_pushboolean(L, 1);
    lua_setglobal(L, "IRONBEE_MODLUA");
    lua_pushstring(L, VERSION);
    lua_setglobal(L, "IRONBEE_VERSION");

    /* Setup search paths before ffi, api, etc loading. */
    rc = modlua_setup_searchpath(ib, L);
    if (rc != IB_OK) {
        return rc;
    }

    /* Load ffi, api, etc. */
    rc = modlua_preload(ib, L);
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to pre-load Lua files.");
        return rc;
    }

    /* Set package paths if configured. */
    if (cfg->pkg_path) {
        ib_log_debug(
            ib,
            "Using lua package.path=\"%s\"",
             cfg->pkg_path);
        lua_getfield(L, -1, "path");
        lua_pushstring(L, cfg->pkg_path);
        lua_setglobal(L, "path");
    }
    if (cfg->pkg_cpath) {
        ib_log_debug(
            ib,
            "Using lua package.cpath=\"%s\"",
            cfg->pkg_cpath);
        lua_getfield(L, -1, "cpath");
        lua_pushstring(L, cfg->pkg_cpath);
        lua_setglobal(L, "cpath");
    }

    lua_rc = luaJIT_setmode(L, 0, LUAJIT_MODE_ENGINE|LUAJIT_MODE_OFF);
    if (lua_rc == 0) {
        ib_log_error(ib, "Failed to disable Lua JIT");
    }

    *Lout = L;

    return IB_OK;
}

static ib_status_t modlua_reload_ctx(
    ib_engine_t  *ib,
    ib_module_t  *module,
    ib_context_t *ctx,
    lua_State    *L
)
{
    assert(ib != NULL);
    assert(ctx != NULL);
    assert(L != NULL);
    assert(module != NULL);

    ib_status_t           rc;
    ib_status_t           tmp_rc = IB_OK;
    modlua_cfg_t         *cfg;
    const ib_list_node_t *node;

    rc = ib_context_module_config(ctx, module, &cfg);
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to retrieve modlua configuration.");
        return rc;
    }

    IB_LIST_LOOP_CONST(cfg->reloads, node) {
        const modlua_reload_t *reload =
            (const modlua_reload_t *)ib_list_node_data_const(node);

        switch(reload->type) {
            case MODLUA_RELOAD_MODULE:
                tmp_rc = modlua_module_load_lua(
                    ib,
                    reload->file,
                    reload->module,
                    L);
                break;
            case MODLUA_RELOAD_RULE:
                tmp_rc = ib_lua_load_func(
                    ib,
                    L,
                    reload->file,
                    reload->rule_id);
                break;
        }

        if (rc == IB_OK && tmp_rc != IB_OK) {
            ib_log_error(
                ib,
                "Failed to reload Lua rule or module \"%s\".",
                reload->file);
            rc = tmp_rc;
        }
    }

    return rc;
}

ib_status_t modlua_record_reload(
    ib_engine_t          *ib,
    modlua_cfg_t         *cfg,
    modlua_reload_type_t  type,
    ib_module_t          *module,
    const char           *rule_id,
    const char           *file
)
{
    assert(ib           != NULL);
    assert(cfg          != NULL);
    assert(cfg->reloads != NULL);
    assert(file         != NULL);

    ib_mm_t          mm;
    ib_status_t      rc;
    modlua_reload_t *data;

    mm = ib_engine_mm_config_get(ib);

    data = ib_mm_alloc(mm, sizeof(*data));
    if (data == NULL) {
        return IB_EALLOC;
    }

    /* Record type. */
    data->type = type;

    /* Record what the user gave us for a module structure. */
    data->module = module;

    /* Copy file name. */
    data->file = ib_mm_strdup(mm, file);
    if (data->file == NULL) {
        ib_log_error(ib, "Failed to copy file name \"%s\".", file);
        return IB_EALLOC;
    }

    /* Copy rule_id. */
    if (rule_id != NULL) {
        data->rule_id = ib_mm_strdup(mm, rule_id);
        if (data->rule_id == NULL) {
            ib_log_error(ib, "Failed to copy rule_id \"%s\".", rule_id);
            return IB_EALLOC;
        }
    }

    rc = ib_list_push(cfg->reloads, data);
    if (rc != IB_OK) {
        return rc;
    }

    return IB_OK;
}

ib_status_t modlua_reload_ctx_main(
    ib_engine_t *ib,
    ib_module_t *module,
    lua_State   *L
)
{
    assert(ib     != NULL);
    assert(module != NULL);
    assert(L      != NULL);

    ib_status_t   rc;
    ib_context_t *ctx = ib_context_main(ib);

    /* Reload this context. */
    rc = modlua_reload_ctx(ib, module, ctx, L);
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to load main context into Lua stack.");
        return rc;
    }

    return IB_OK;
}

ib_status_t modlua_reload_ctx_except_main(
    ib_engine_t *ib,
    ib_module_t  *module,
    ib_context_t *ctx,
    lua_State    *L
)
{
    assert(ib     != NULL);
    assert(module != NULL);
    assert(ctx    != NULL);
    assert(L      != NULL);

    ib_status_t rc;

    /* Do not reload the main context. */
    if (ctx == ib_context_main(ib)) {
        return IB_OK;
    }

    /* Reload the parent context first. */
    rc = modlua_reload_ctx_except_main(
        ib,
        module,
        ib_context_parent_get(ctx),
        L);
    if (rc != IB_OK) {
        return rc;
    }

    /* Reload this context. */
    rc = modlua_reload_ctx(ib, module, ctx, L);
    if (rc != IB_OK) {
        ib_log_error(
            ib,
            "Failed to load context \"%s\" into Lua stack.",
            ib_context_name_get(ctx));
        return rc;
    }

    return IB_OK;
}

static ib_status_t lua_pool_create_fn(void *resource, void *cbdata)
{
    assert(resource != NULL);
    assert(cbdata != NULL);

    modlua_runtime_t *modlua_runtime;
    ib_mpool_lite_t  *mp;
    ib_status_t       rc;
    modlua_cfg_t     *cfg;
    ib_context_t     *ctx;
    ib_engine_t      *ib;
    ib_module_t      *module;
    modlua_runtime_cbdata_t *modlua_runtime_cbdata =
        (modlua_runtime_cbdata_t *)cbdata;

    assert(modlua_runtime_cbdata->ib     != NULL);
    assert(modlua_runtime_cbdata->module != NULL);

    /* Alias some callback values. */
    ib     = modlua_runtime_cbdata->ib;
    module = modlua_runtime_cbdata->module;

    rc = ib_mpool_lite_create(&mp);
    if (rc != IB_OK) {
        return rc;
    }

    modlua_runtime =
        ib_mm_calloc(ib_mm_mpool_lite(mp), 1, sizeof(*modlua_runtime));
    if (modlua_runtime == NULL) {
        rc = IB_EALLOC;
        goto exit_failure;
    }

    ctx = ib_context_main(ib);

    rc = modlua_cfg_get(ib, ctx, &cfg);
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to fetch lua configuration.");
        goto exit_failure;
    }

    modlua_runtime->use_count = 0;
    modlua_runtime->mp        = mp;

    /* Create a new Lua State. */
    rc = modlua_newstate(ib, cfg, &(modlua_runtime->L));
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to create Lua stack.");
        goto exit_failure;
    }

    /* Preload the user's main context. */
    rc = modlua_reload_ctx_main(ib, module, modlua_runtime->L);
    if (rc != IB_OK) {
        ib_log_error(ib, "Failed to configure Lua stack.");
        goto exit_failure;
    }

    *(void **)resource = modlua_runtime;

    return IB_OK;

exit_failure:
    ib_mpool_lite_destroy(mp);
    return rc;
}

static void lua_pool_destroy_fn(void *resource, void *cbdata)
{
    assert(resource != NULL);

    modlua_runtime_t *modlua_runtime = (modlua_runtime_t *)resource;

    ib_mpool_lite_t *mp = modlua_runtime->mp;
    lua_State       *L  = modlua_runtime->L;

    assert(mp != NULL);
    assert(L != NULL);

    /* Clear the struct to provoke faster crashes. */
    memset(modlua_runtime, 0, sizeof(*modlua_runtime));

    /* Set the use count to -1 to signal that this is a cleared structure. */
    modlua_runtime->use_count = -1;

    /* Finally, release the resources. */
    lua_close(L);
    ib_mpool_lite_destroy(mp);
}

static void error_parse(
  std::istream &errors,
  bool warning_only,
  messaget &message)
{
  std::string line;

  while(std::getline(errors, line))
    error_parse_line(line, warning_only, message);
}

bool c_preprocess(
  std::istream &instream,
  std::ostream &outstream,
  message_handlert &message_handler)
{
  temporary_filet tmp_file("tmp.stdin", ".c");

  std::ofstream tmp(tmp_file());

  if(!tmp)
  {
    messaget message(message_handler);
    message.error() << "failed to open temporary file" << messaget::eom;
    return true; // error
  }

  tmp << instream.rdbuf(); // copy

  tmp.close(); // flush

  bool result=c_preprocess(tmp_file(), outstream, message_handler);

  return result;
}

static bool is_dot_i_file(const std::string &path)
{
  return has_suffix(path, ".i") || has_suffix(path, ".ii");
}

bool c_preprocess(
  const std::string &path,
  std::ostream &outstream,
  message_handlert &message_handler)
{
  switch(config.ansi_c.preprocessor)
  {
  case configt::ansi_ct::preprocessort::CODEWARRIOR:
    return c_preprocess_codewarrior(path, outstream, message_handler);

  case configt::ansi_ct::preprocessort::GCC:
    return
      c_preprocess_gcc_clang(
        path, outstream, message_handler, config.ansi_c.preprocessor);

  case configt::ansi_ct::preprocessort::CLANG:
    return
      c_preprocess_gcc_clang(
        path, outstream, message_handler, config.ansi_c.preprocessor);

  case configt::ansi_ct::preprocessort::VISUAL_STUDIO:
    return c_preprocess_visual_studio(path, outstream, message_handler);

  case configt::ansi_ct::preprocessort::ARM:
    return c_preprocess_arm(path, outstream, message_handler);

  case configt::ansi_ct::preprocessort::NONE:
    return c_preprocess_none(path, outstream, message_handler);
  }

  // not reached
  return true;
}

void postprocess_codewarrior(
  std::istream &instream,
  std::ostream &outstream)
{
  // CodeWarrior prepends some header to the file,
  // marked with '#' signs.
  // We skip over it.
  //
  // CodeWarrior has an ugly way of marking lines, e.g.:
  //
  // /* #line 1      "__ppc_eabi_init.cpp"   /* stack depth 0 */
  //
  // We remove the initial '/* ' prefix

  std::string line;

  while(instream)
  {
    std::getline(instream, line);

    if(line.size()>=2 &&
       line[0]=='#' && (line[1]=='#' || line[1]==' ' || line[1]=='\t'))
    {
      // skip the line!
    }
    else if(line.size()>=3 &&
            line[0]=='/' && line[1]=='*' && line[2]==' ')
    {
      outstream << line.c_str()+3 << "\n"; // strip the '/* '
    }
    else
      outstream << line << "\n";
  }
}

bool c_preprocess_codewarrior(
  const std::string &file,
  std::ostream &outstream,
  message_handlert &message_handler)
{
  // check extension
  if(is_dot_i_file(file))
    return c_preprocess_none(file, outstream, message_handler);

  // preprocessing
  messaget message(message_handler);

  temporary_filet stderr_file("tmp.stderr", "");

  std::vector<std::string> command = {
    "mwcceppc", "-E", "-P", "-D__CPROVER__", "-ppopt", "line", "-ppopt full"};

  for(const auto &define : config.ansi_c.defines)
    command.push_back(" -D" + define);

  for(const auto &include_path : config.ansi_c.include_paths)
    command.push_back(" -I" + include_path);

  for(const auto &include_file : config.ansi_c.include_files)
  {
    command.push_back(" -include");
    command.push_back(include_file);
  }

  for(const auto &opt : config.ansi_c.preprocessor_options)
    command.push_back(opt);

  temporary_filet tmpi("tmp.cl", "");
  command.push_back(file);
  command.push_back("-o");
  command.push_back(tmpi());

  int result = run(command[0], command, "", "", stderr_file());

  std::ifstream stream_i(tmpi());

  if(stream_i)
  {
    postprocess_codewarrior(stream_i, outstream);

    stream_i.close();
  }
  else
  {
    message.error() << "Preprocessing failed (fopen failed)"
                    << messaget::eom;
    return true;
  }

  // errors/warnings
  std::ifstream stderr_stream(stderr_file());
  error_parse(stderr_stream, result==0, message);

  if(result!=0)
  {
    message.error() << "Preprocessing failed" << messaget::eom;
    return true;
  }

  return false;
}

bool c_preprocess_gcc_clang(
  const std::string &file,
  std::ostream &outstream,
  message_handlert &message_handler,
  configt::ansi_ct::preprocessort preprocessor)
{
  // check extension
  if(is_dot_i_file(file))
    return c_preprocess_none(file, outstream, message_handler);

  // preprocessing
  messaget message(message_handler);

  temporary_filet stderr_file("tmp.stderr", "");

  std::vector<std::string> argv;

  if(preprocessor==configt::ansi_ct::preprocessort::CLANG)
    argv.push_back("clang");
  else
    argv.push_back("gcc");

  argv.push_back("-E");
  argv.push_back("-D__CPROVER__");

  const irep_idt &arch = config.ansi_c.arch;

  if(config.ansi_c.pointer_width == 16)
  {
    if(arch == "i386" || arch == "x86_64" || arch == "x32")
      argv.push_back("-m16");
    else if(has_prefix(id2string(arch), "mips"))
      argv.push_back("-mips16");
  }
  else if(config.ansi_c.pointer_width == 32)
  {
    if(arch == "i386" || arch == "x86_64")
      argv.push_back("-m32");
    else if(arch == "x32")
      argv.push_back("-mx32");
    else if(has_prefix(id2string(arch), "mips"))
      argv.push_back("-mabi=32");
    else if(arch == "powerpc" || arch == "ppc64" || arch == "ppc64le")
      argv.push_back("-m32");
    else if(arch == "s390" || arch == "s390x")
      argv.push_back("-m31"); // yes, 31, not 32!
    else if(arch == "sparc" || arch == "sparc64")
      argv.push_back("-m32");
  }
  else if(config.ansi_c.pointer_width == 64)
  {
    if(arch == "i386" || arch == "x86_64" || arch == "x32")
      argv.push_back("-m64");
    else if(has_prefix(id2string(arch), "mips"))
      argv.push_back("-mabi=64");
    else if(arch == "powerpc" || arch == "ppc64" || arch == "ppc64le")
      argv.push_back("-m64");
    else if(arch == "s390" || arch == "s390x")
      argv.push_back("-m64");
    else if(arch == "sparc" || arch == "sparc64")
      argv.push_back("-m64");
  }

  // The width of wchar_t depends on the OS!
  if(config.ansi_c.wchar_t_width == config.ansi_c.short_int_width)
    argv.push_back("-fshort-wchar");

  if(config.ansi_c.char_is_unsigned)
    argv.push_back("-funsigned-char");

  if(config.ansi_c.os == configt::ansi_ct::ost::NO_OS)
    argv.push_back("-nostdinc");

  // Set the standard
  if(
    has_suffix(file, ".cpp") || has_suffix(file, ".CPP") ||
#ifndef _WIN32
    has_suffix(file, ".C") ||
#endif
    has_suffix(file, ".c++") || has_suffix(file, ".C++") ||
    has_suffix(file, ".cp") || has_suffix(file, ".CP") ||
    has_suffix(file, ".cc") || has_suffix(file, ".cxx"))
  {
    switch(config.cpp.cpp_standard)
    {
    case configt::cppt::cpp_standardt::CPP98:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c++98");
      else
#endif
        argv.push_back("-std=gnu++98");
      break;

    case configt::cppt::cpp_standardt::CPP03:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c++03");
      else
#endif
        argv.push_back("-std=gnu++03");
      break;

    case configt::cppt::cpp_standardt::CPP11:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c++11");
      else
#endif
        argv.push_back("-std=gnu++11");
      break;

    case configt::cppt::cpp_standardt::CPP14:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c++14");
      else
#endif
        argv.push_back("-std=gnu++14");
      break;
    }
  }
  else
  {
    switch(config.ansi_c.c_standard)
    {
    case configt::ansi_ct::c_standardt::C89:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c89");
      else
#endif
        argv.push_back("-std=gnu89");
      break;

    case configt::ansi_ct::c_standardt::C99:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c99");
      else
#endif
        argv.push_back("-std=gnu99");
      break;

    case configt::ansi_ct::c_standardt::C11:
#if defined(__OpenBSD__)
      if(preprocessor == configt::ansi_ct::preprocessort::CLANG)
        argv.push_back("-std=c11");
      else
#endif
        argv.push_back("-std=gnu11");
      break;
    }
  }

  for(const auto &define : config.ansi_c.defines)
    argv.push_back("-D" + define);

  for(const auto &include_path : config.ansi_c.include_paths)
    argv.push_back("-I" + include_path);

  for(const auto &include_file : config.ansi_c.include_files)
  {
    argv.push_back("-include");
    argv.push_back(include_file);
  }

  for(const auto &opt : config.ansi_c.preprocessor_options)
    argv.push_back(opt);

  int result;

  #if 0
  // the following forces the mode
  switch(config.ansi_c.mode)
  {
  case configt::ansi_ct::flavourt::GCC_C: command+=" -x c"; break;
  case configt::ansi_ct::flavourt::GCC_CPP: command+=" -x c++"; break;
  default:
    {
    }
  }
  #endif

  // the file that is to be preprocessed
  argv.push_back(file);

  // execute clang or gcc
  result = run(argv[0], argv, "", outstream, stderr_file());

  // errors/warnings
  std::ifstream stderr_stream(stderr_file());
  error_parse(stderr_stream, result==0, message);

  if(result!=0)
  {
    message.error() << "GCC preprocessing failed" << messaget::eom;
    return true;
  }

  return false;
}

bool c_preprocess_arm(
  const std::string &file,
  std::ostream &outstream,
  message_handlert &message_handler)
{
  // check extension
  if(is_dot_i_file(file))
    return c_preprocess_none(file, outstream, message_handler);

  // preprocessing using armcc
  messaget message(message_handler);

  temporary_filet stderr_file("tmp.stderr", "");

  std::vector<std::string> argv;

  argv.push_back("armcc");
  argv.push_back("-E");
  argv.push_back("-D__CPROVER__");

  if(config.ansi_c.endianness == configt::ansi_ct::endiannesst::IS_BIG_ENDIAN)
    argv.push_back("--bigend");
  else
    argv.push_back("--littleend");

  if(config.ansi_c.char_is_unsigned)
    argv.push_back("--unsigned_chars");
  else
    argv.push_back("--signed_chars");

  // Set the standard
  switch(config.ansi_c.c_standard)
  {
  case configt::ansi_ct::c_standardt::C89:
    argv.push_back("--c90");
    break;

  case configt::ansi_ct::c_standardt::C99:
  case configt::ansi_ct::c_standardt::C11:
    argv.push_back("--c99");
    break;
  }

  for(const auto &define : config.ansi_c.defines)
    argv.push_back("-D" + define);

  for(const auto &include_path : config.ansi_c.include_paths)
    argv.push_back("-I" + include_path);

  // the file that is to be preprocessed
  argv.push_back(file);

  int result;

  // execute armcc
  result = run(argv[0], argv, "", outstream, stderr_file());

  // errors/warnings
  std::ifstream stderr_stream(stderr_file());
  error_parse(stderr_stream, result==0, message);

  if(result!=0)
  {
    message.error() << "ARMCC preprocessing failed" << messaget::eom;
    return true;
  }

  return false;
}

bool c_preprocess_none(
  const std::string &file,
  std::ostream &outstream,
  message_handlert &message_handler)
{
  #ifdef _MSC_VER
  std::ifstream infile(widen(file));
  #else
  std::ifstream infile(file);
  #endif

  if(!infile)
  {
    messaget message(message_handler);
    message.error() << "failed to open '" << file << "'" << messaget::eom;
    return true;
  }

  if(config.ansi_c.mode==configt::ansi_ct::flavourt::CODEWARRIOR)
  {
    // special treatment for "/* #line"
    postprocess_codewarrior(infile, outstream);
  }
  else
  {
    char ch;

    while(infile.read(&ch, 1))
      outstream << ch;
  }

  return false;
}

bool test_c_preprocessor(message_handlert &message_handler)
{
  std::ostringstream out;
  std::istringstream in(c_test_program);

  return c_preprocess(in, out, message_handler);
}

static int do_database_write(db_conn_t *db_conn)
{
	assert(db_conn->param);

	int ret = db_conn->param->on_write_ready(db_conn->param, db_conn->conn);

	if (!ret)
		db_conn->flags &= ~IS_WRITING;
	else if (ret < 0) {
		ERROR(PQerrorMessage(db_conn->conn));
		on_database_error(db_conn, DB_ERROR);
	}
	else {
		h2o_socket_notify_write(db_conn->sock, on_database_write_ready);
		ret = 0;
	}

	return ret;
}

static int do_execute_query(db_conn_t *db_conn, bool direct_notification)
{
	const int ec = db_conn->param->flags & IS_PREPARED ?
	               PQsendQueryPrepared(db_conn->conn,
	                                   db_conn->param->command,
	                                   db_conn->param->nParams,
	                                   db_conn->param->paramValues,
	                                   db_conn->param->paramLengths,
	                                   db_conn->param->paramFormats,
	                                   db_conn->param->resultFormat) :
	               PQsendQuery(db_conn->conn, db_conn->param->command);
	int ret = 1;

	if (ec) {
		if (db_conn->param->flags & IS_SINGLE_ROW)
			PQsetSingleRowMode(db_conn->conn);

		db_conn->h2o_timeout_entry.cb = on_database_timeout;
		h2o_timeout_link(db_conn->ctx->event_loop.h2o_ctx.loop,
		                 &db_conn->ctx->db_state.h2o_timeout,
		                 &db_conn->h2o_timeout_entry);
		h2o_socket_read_start(db_conn->sock, on_database_read_ready);

		const int send_status = PQflush(db_conn->conn);

		if (send_status < 0) {
			if (direct_notification)
				db_conn->param = NULL;

			LIBRARY_ERROR("PQflush", PQerrorMessage(db_conn->conn));
			on_database_error(db_conn, DB_ERROR);
		}
		else {
			ret = 0;

			if (send_status)
				h2o_socket_notify_write(db_conn->sock, on_database_write_ready);
		}
	}
	else {
		if (direct_notification)
			db_conn->param = NULL;

		ERROR(PQerrorMessage(db_conn->conn));
		on_database_error(db_conn, DB_ERROR);
	}

	return ret;
}

static void error_notification(thread_context_t *ctx, bool timeout, const char *error_string)
{
	if (!--ctx->db_state.db_conn_num) {
		// We don't want to keep requests waiting for an unbounded amount of time.
		list_t *iter = ctx->db_state.queries.head;

		ctx->db_state.queries.head = NULL;
		ctx->db_state.queries.tail = &ctx->db_state.queries.head;
		ctx->db_state.query_num = 0;

		if (iter)
			do {
				db_query_param_t * const param = H2O_STRUCT_FROM_MEMBER(db_query_param_t, l, iter);

				// The callback may free the db_query_param_t structure.
				iter = iter->next;

				if (timeout)
					param->on_timeout(param);
				else
					param->on_error(param, error_string);
			} while (iter);
	}
}

static void on_database_connect_error(db_conn_t *db_conn, bool timeout, const char *error_string)
{
	thread_context_t * const ctx = db_conn->ctx;

	error_notification(ctx, timeout, error_string);
	h2o_timeout_unlink(&db_conn->h2o_timeout_entry);
	h2o_socket_read_stop(db_conn->sock);
	h2o_socket_close(db_conn->sock);
	PQfinish(db_conn->conn);
	free(db_conn);
}

static void on_database_connect_timeout(h2o_timeout_entry_t *entry)
{
	db_conn_t * const db_conn = H2O_STRUCT_FROM_MEMBER(db_conn_t, h2o_timeout_entry, entry);

	ERROR(DB_TIMEOUT_ERROR);
	on_database_connect_error(db_conn, true, DB_TIMEOUT_ERROR);
}

static void on_database_error(db_conn_t *db_conn, const char *error_string)
{
	if (db_conn->prepared_statement)
		on_database_connect_error(db_conn, false, error_string);
	else {
		if (db_conn->param) {
			db_conn->param->on_error(db_conn->param, error_string);
			db_conn->param = NULL;
		}

		if (PQstatus(db_conn->conn) == CONNECTION_OK) {
			h2o_timeout_unlink(&db_conn->h2o_timeout_entry);
			h2o_socket_read_stop(db_conn->sock);
			process_query(db_conn);
		}
		else
			start_database_connect(db_conn->ctx, db_conn);
	}
}

static void on_database_read_ready(h2o_socket_t *db_sock, const char *err)
{
	db_conn_t * const db_conn = db_sock->data;

	if (err)
		ERROR(err);
	else {
		if (PQconsumeInput(db_conn->conn)) {
			const int send_status = PQflush(db_conn->conn);

			if (send_status > 0)
				h2o_socket_notify_write(db_conn->sock, on_database_write_ready);

			if (send_status >= 0) {
				while (!PQisBusy(db_conn->conn)) {
					PGresult * const result = PQgetResult(db_conn->conn);

					if (db_conn->param)
						switch (db_conn->param->on_result(db_conn->param, result)) {
							case WANT_WRITE:
								db_conn->flags |= IS_WRITING;

								if (do_database_write(db_conn))
									return;

								break;
							case DONE:
								db_conn->param = NULL;
								h2o_timeout_unlink(&db_conn->h2o_timeout_entry);
								break;
							default:
								break;
						}
					else if (result) {
						if (PQresultStatus(result) != PGRES_COMMAND_OK)
							LIBRARY_ERROR("PQresultStatus", PQresultErrorMessage(result));

						PQclear(result);
					}

					if (!result) {
						assert(!db_conn->param);
						h2o_timeout_unlink(&db_conn->h2o_timeout_entry);
						h2o_socket_read_stop(db_conn->sock);
						process_query(db_conn);
						break;
					}
				}

				return;
			}
		}

		ERROR(PQerrorMessage(db_conn->conn));
	}

	on_database_error(db_conn, DB_ERROR);
}

static void on_database_timeout(h2o_timeout_entry_t *entry)
{
	db_conn_t * const db_conn = H2O_STRUCT_FROM_MEMBER(db_conn_t, h2o_timeout_entry, entry);

	ERROR(DB_TIMEOUT_ERROR);

	if (db_conn->param) {
		db_conn->param->on_timeout(db_conn->param);
		db_conn->param = NULL;
	}

	start_database_connect(db_conn->ctx, db_conn);
}

static void on_database_write_ready(h2o_socket_t *db_sock, const char *err)
{
	db_conn_t * const db_conn = db_sock->data;

	if (err) {
		ERROR(err);
		on_database_error(db_conn, DB_ERROR);
	}
	else {
		const int send_status = PQflush(db_conn->conn);

		if (!send_status) {
			if (db_conn->flags & IS_WRITING && db_conn->param)
				do_database_write(db_conn);
		}
		else if (send_status < 0) {
			LIBRARY_ERROR("PQflush", PQerrorMessage(db_conn->conn));
			on_database_error(db_conn, DB_ERROR);
		}
		else
			h2o_socket_notify_write(db_conn->sock, on_database_write_ready);
	}
}

static void poll_database_connection(h2o_socket_t *db_sock, const char *err)
{
	db_conn_t * const db_conn = db_sock->data;

	if (err)
		ERROR(err);
	else {
		const PostgresPollingStatusType status = db_conn->flags & IS_RESETTING ?
		                                         PQresetPoll(db_conn->conn) :
		                                         PQconnectPoll(db_conn->conn);

		switch (status) {
			case PGRES_POLLING_WRITING:
				if (!h2o_socket_is_writing(db_conn->sock))
					h2o_socket_notify_write(db_conn->sock, poll_database_connection);

				h2o_socket_read_stop(db_conn->sock);
				return;
			case PGRES_POLLING_OK:
				if (PQsetnonblocking(db_conn->conn, 1)) {
					LIBRARY_ERROR("PQsetnonblocking", PQerrorMessage(db_conn->conn));
					break;
				}

				h2o_timeout_unlink(&db_conn->h2o_timeout_entry);
				h2o_socket_read_stop(db_conn->sock);
				process_query(db_conn);
				return;
			case PGRES_POLLING_READING:
				h2o_socket_read_start(db_conn->sock, poll_database_connection);
				return;
			default:
				ERROR(PQerrorMessage(db_conn->conn));
		}
	}

	on_database_connect_error(db_conn, false, DB_ERROR);
}

void BX_CPP_AttrRegparmN(3)
BX_CPU_C::write_virtual_byte_32(unsigned s, Bit32u offset, Bit8u data)
{
  Bit32u laddr;
  bx_segment_reg_t *seg = &BX_CPU_THIS_PTR sregs[s];

  BX_ASSERT(BX_CPU_THIS_PTR cpu_mode != BX_MODE_LONG_64);

  if (seg->cache.valid & SegAccessWOK) {
    if (offset <= seg->cache.u.segment.limit_scaled) {
accessOK:
      laddr = get_laddr32(s, offset);
      unsigned tlbIndex = BX_TLB_INDEX_OF(laddr, 0);
      Bit32u lpf = LPFOf(laddr);
      bx_TLB_entry *tlbEntry = &BX_CPU_THIS_PTR TLB.entry[tlbIndex];
      if (tlbEntry->lpf == lpf) {
        // See if the TLB entry privilege level allows us write access
        // from this CPL.
        if (tlbEntry->accessBits & (0x04 << USER_PL)) {
          bx_hostpageaddr_t hostPageAddr = tlbEntry->hostPageAddr;
          Bit32u pageOffset = PAGE_OFFSET(laddr);
          bx_phy_address pAddr = tlbEntry->ppf | pageOffset;
          BX_NOTIFY_LIN_MEMORY_ACCESS(laddr, pAddr, 1, CPL, BX_WRITE, (Bit8u*) &data);
          Bit8u *hostAddr = (Bit8u*) (hostPageAddr | pageOffset);
          pageWriteStampTable.decWriteStamp(pAddr, 1);
          *hostAddr = data;
          return;
        }
      }
      access_write_linear(laddr, 1, CPL, (void *) &data);
      return;
    }
    else {
      BX_ERROR(("write_virtual_byte_32(): segment limit violation"));
      exception(int_number(s), 0);
    }
  }

void BX_CPP_AttrRegparmN(3)
BX_CPU_C::write_virtual_dword_32(unsigned s, Bit32u offset, Bit32u data)
{
  Bit32u laddr;
  bx_segment_reg_t *seg = &BX_CPU_THIS_PTR sregs[s];

  BX_ASSERT(BX_CPU_THIS_PTR cpu_mode != BX_MODE_LONG_64);

  if (seg->cache.valid & SegAccessWOK) {
    if (offset < (seg->cache.u.segment.limit_scaled-2)) {
accessOK:
      laddr = get_laddr32(s, offset);
      unsigned tlbIndex = BX_TLB_INDEX_OF(laddr, 3);
#if BX_SUPPORT_ALIGNMENT_CHECK && BX_CPU_LEVEL >= 4
      Bit32u lpf = AlignedAccessLPFOf(laddr, (3 & BX_CPU_THIS_PTR alignment_check_mask));
#else
      Bit32u lpf = LPFOf(laddr);
#endif    
      bx_TLB_entry *tlbEntry = &BX_CPU_THIS_PTR TLB.entry[tlbIndex];
      if (tlbEntry->lpf == lpf) {
        // See if the TLB entry privilege level allows us write access
        // from this CPL.
        if (tlbEntry->accessBits & (0x04 << USER_PL)) {
          bx_hostpageaddr_t hostPageAddr = tlbEntry->hostPageAddr;
          Bit32u pageOffset = PAGE_OFFSET(laddr);
          bx_phy_address pAddr = tlbEntry->ppf | pageOffset;
          BX_NOTIFY_LIN_MEMORY_ACCESS(laddr, pAddr, 4, CPL, BX_WRITE, (Bit8u*) &data);
          Bit32u *hostAddr = (Bit32u*) (hostPageAddr | pageOffset);
          pageWriteStampTable.decWriteStamp(pAddr, 4);
          WriteHostDWordToLittleEndian(hostAddr, data);
          return;
        }
      }

#if BX_CPU_LEVEL >= 4 && BX_SUPPORT_ALIGNMENT_CHECK
      if (BX_CPU_THIS_PTR alignment_check()) {
        if (laddr & 3) {
          BX_ERROR(("write_virtual_dword_32(): #AC misaligned access"));
          exception(BX_AC_EXCEPTION, 0);
        }
      }
#endif

      access_write_linear(laddr, 4, CPL, (void *) &data);
      return;
    }
    else {
      BX_ERROR(("write_virtual_dword_32(): segment limit violation"));
      exception(int_number(s), 0);
    }
  }

